import { Canvas, useFrame } from '@react-three/fiber'
import { useCallback, useEffect, useMemo, useRef, useState, type MutableRefObject, type PointerEvent as ReactPointerEvent } from 'react'
import * as THREE from 'three'
import { Arwing, CameraRig, Reticle } from './Arwing'
import { Enemy } from './Enemy'
import { Laser } from './Laser'
import { SceneEffects } from './SceneEffects'
import { Terrain } from './Terrain'
import { buildWave, getDifficulty, normalizedLevelProgress } from './difficulty'
import type {
  EnemyHandle,
  EnemySpawn,
  FlightRuntime,
  InputState,
  LaserHandle,
  LaserOwner,
  PlayerState,
  TeammateId,
  WorldState,
} from './types'

interface Encounter {
  at: number
  enemies: Array<Omit<EnemySpawn, 'id' | 'bornAt'>>
}

interface LaserSpec {
  id: string
  owner: LaserOwner
  origin: THREE.Vector3
  direction: THREE.Vector3
  speed: number
}

const TEAM = [
  { id: 'lyra' as const, name: 'Lyra', role: 'scout' },
  { id: 'rook' as const, name: 'Rook', role: 'tactician' },
  { id: 'pip' as const, name: 'Pip', role: 'support' },
]

const ENCOUNTERS: Encounter[] = [
  {
    at: 0,
    enemies: [
      { variant: 'scout', x: -5, y: 2.2, z: -62, health: 1 },
      { variant: 'scout', x: 0, y: 3.3, z: -68, health: 1 },
      { variant: 'scout', x: 5, y: 1.8, z: -74, health: 1 },
    ],
  },
  {
    at: 42,
    enemies: [
      { variant: 'scout', x: -5.8, y: 1.4, z: -72, health: 1, target: 'lyra' },
      { variant: 'scout', x: -3.7, y: 1.2, z: -78, health: 1 },
      { variant: 'heavy', x: 4.6, y: 3.4, z: -84, health: 3 },
    ],
  },
  {
    at: 88,
    enemies: [
      { variant: 'turret', x: -7, y: -1.3, z: -68, health: 2 },
      { variant: 'turret', x: 0, y: -1.3, z: -86, health: 2 },
      { variant: 'turret', x: 7, y: -1.3, z: -76, health: 2 },
      { variant: 'scout', x: 0, y: 5, z: -98, health: 1, target: 'rook' },
    ],
  },
  {
    at: 148,
    enemies: [
      { variant: 'heavy', x: -5.5, y: 2.7, z: -76, health: 3 },
      { variant: 'heavy', x: 5.5, y: 2.7, z: -90, health: 3 },
      { variant: 'scout', x: -1.5, y: 4.8, z: -108, health: 1 },
      { variant: 'scout', x: 1.5, y: 4.8, z: -113, health: 1, target: 'pip' },
    ],
  },
  {
    at: 226,
    enemies: [
      { variant: 'turret', x: -7.4, y: -1.5, z: -74, health: 2 },
      { variant: 'turret', x: 7.4, y: -1.5, z: -82, health: 2 },
      { variant: 'heavy', x: 0, y: 4, z: -104, health: 3 },
    ],
  },
  {
    at: 314,
    enemies: [
      { variant: 'scout', x: -5.7, y: 3.5, z: -78, health: 1 },
      { variant: 'scout', x: 5.7, y: 3.5, z: -84, health: 1 },
      { variant: 'heavy', x: 0, y: 0.5, z: -106, health: 3 },
    ],
  },
  {
    at: 378,
    enemies: [{ variant: 'carrier', x: 0, y: 2.2, z: -96, health: 22 }],
  },
]

const initialPlayer = (): PlayerState => ({
  position: new THREE.Vector3(0, 0, 2.5),
  target: new THREE.Vector3(0, 0, 2.5),
  velocity: new THREE.Vector3(),
  invincibleUntil: 0,
  barrel: { active: false, direction: 1, startedAt: 0 },
})

const initialWorld = (): WorldState => ({ distance: 0, speed: 24, boost: false, time: 0 })
const initialInput = (): InputState => ({ keys: new Set(), justPressed: new Set() })

export function Game() {
  const [runId, setRunId] = useState(0)
  const [running, setRunning] = useState(true)
  const [stageState, setStageState] = useState<'live' | 'won' | 'lost'>('live')
  const [score, setScore] = useState(0)
  const [shield, setShield] = useState(100)
  const [bombs, setBombs] = useState(3)
  const [status, setStatus] = useState('ESCORT THE CONVOY · CLEAR THE SKYLINE')
  const [distance, setDistance] = useState(0)
  const [bossHealth, setBossHealth] = useState(0)
  const [bossMaxHealth, setBossMaxHealth] = useState(0)
  const [teammates, setTeammates] = useState<Record<TeammateId, 'ready' | 'threatened' | 'down'>>({ lyra: 'ready', rook: 'ready', pip: 'ready' })

  const input = useRef<InputState>(initialInput())
  const world = useRef<WorldState>(initialWorld())
  const player = useRef<PlayerState>(initialPlayer())
  const lasers = useRef(new Map<string, LaserHandle>())
  const enemies = useRef(new Map<string, EnemyHandle>())
  const encounterCursor = useRef(0)
  const spawnedEnemies = useRef<EnemySpawn[]>([])
  const lastShot = useRef(0)
  const lastHudUpdate = useRef(0)
  const laserSequence = useRef(0)
  const lastTap = useRef(Number.NEGATIVE_INFINITY)
  const gameOver = useRef(false)

  const [enemySpawns, setEnemySpawns] = useState<EnemySpawn[]>([])
  const [laserSpecs, setLaserSpecs] = useState<LaserSpec[]>([])

  const flight = useMemo<FlightRuntime>(() => ({
    input: input.current,
    world: world.current,
    player: player.current,
  }), [])

  const triggerBarrel = useCallback((direction: number) => {
    const now = world.current.time
    if (player.current.barrel.active || now < player.current.invincibleUntil) return
    player.current.barrel = { active: true, direction, startedAt: now }
    player.current.invincibleUntil = now + 0.9
    setStatus('BARREL ROLL · LASERS DEFLECTED')
  }, [])

  useEffect(() => {
    const clearInput = () => {
      input.current.keys.clear()
      input.current.justPressed.clear()
      lastTap.current = Number.NEGATIVE_INFINITY
    }
    const onKeyDown = (event: KeyboardEvent) => {
      const code = event.code
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(code)) event.preventDefault()
      const now = world.current.time
      const horizontal = code === 'ArrowLeft' || code === 'KeyA' ? -1 : code === 'ArrowRight' || code === 'KeyD' ? 1 : 0
      if (!event.repeat) {
        input.current.justPressed.add(code)
        if (horizontal !== 0) {
          if (now - lastTap.current < 0.28) triggerBarrel(horizontal)
          lastTap.current = now
        }
      }
      input.current.keys.add(code)
    }
    const onKeyUp = (event: KeyboardEvent) => input.current.keys.delete(event.code)
    const onBlur = () => clearInput()
    const onVisibilityChange = () => { if (document.hidden) clearInput() }
    window.addEventListener('keydown', onKeyDown)
    window.addEventListener('keyup', onKeyUp)
    window.addEventListener('blur', onBlur)
    document.addEventListener('visibilitychange', onVisibilityChange)
    return () => {
      window.removeEventListener('keydown', onKeyDown)
      window.removeEventListener('keyup', onKeyUp)
      window.removeEventListener('blur', onBlur)
      document.removeEventListener('visibilitychange', onVisibilityChange)
      clearInput()
    }
  }, [triggerBarrel])

  const spawnLaser = useCallback((owner: LaserOwner, origin: THREE.Vector3, direction = new THREE.Vector3(0, 0, owner === 'player' ? -1 : 1), speed = owner === 'player' ? 76 : 42) => {
    // A monotonic sequence avoids collisions when several shots are created
    // before React has committed the previous laser list update.
    const id = `${owner}-${laserSequence.current++}`
    setLaserSpecs((current) => [...current, { id, owner, origin: origin.clone(), direction: direction.clone().normalize(), speed }])
  }, [])

  const registerLaser = useCallback((handle: LaserHandle) => lasers.current.set(handle.id, handle), [])
  const unregisterLaser = useCallback((id: string) => lasers.current.delete(id), [])
  const expireLaser = useCallback((id: string) => {
    const laser = lasers.current.get(id)
    if (laser) laser.alive = false
    setLaserSpecs((current) => current.filter((laser) => laser.id !== id))
  }, [])

  const registerEnemy = useCallback((handle: EnemyHandle) => enemies.current.set(handle.id, handle), [])
  const unregisterEnemy = useCallback((id: string) => enemies.current.delete(id), [])

  const removeEnemy = useCallback((spawn: EnemySpawn) => {
    const handle = enemies.current.get(spawn.id)
    if (handle) handle.alive = false
    setEnemySpawns((current) => current.filter((enemy) => enemy.id !== spawn.id))
    spawnedEnemies.current = spawnedEnemies.current.filter((enemy) => enemy.id !== spawn.id)
    if (spawn.target) {
      setTeammates((current) => current[spawn.target!] === 'threatened' ? { ...current, [spawn.target!]: 'ready' } : current)
      setStatus(`${spawn.target.toUpperCase()} COVERED · KEEP FORMATION`)
    }
    if (spawn.variant === 'carrier') {
      setBossHealth(0)
      setBossMaxHealth(0)
    }
  }, [])

  const damagePlayer = useCallback((amount: number) => {
    if (gameOver.current) return
    setShield((current) => {
      const next = Math.max(0, current - amount)
      if (next === 0) {
        gameOver.current = true
        setStageState('lost')
        setRunning(false)
      }
      return next
    })
  }, [])

  const expireEnemy = useCallback((spawn: EnemySpawn) => {
    if (spawn.variant === 'carrier') {
      gameOver.current = true
      setBossHealth(0)
      setStatus('CARRIER ESCAPED · ESCORT CORRIDOR LOST')
      setStageState('lost')
      setRunning(false)
    } else if (spawn.target) {
      setTeammates((current) => ({ ...current, [spawn.target!]: 'down' }))
      setStatus(`${spawn.target.toUpperCase()} DOWN · FORMATION COMPROMISED`)
    }
    removeEnemy(spawn)
  }, [removeEnemy])

  const spawnEncounter = useCallback((encounter: Encounter, encounterIndex: number) => {
    const difficulty = getDifficulty(normalizedLevelProgress(world.current.distance))
    const wave = buildWave(encounter.enemies, difficulty)
    const spawned = wave.map((enemy, index) => ({
      ...enemy,
      id: `encounter-${encounterIndex}-${index}`,
      bornAt: world.current.distance,
    }))
    spawnedEnemies.current = [...spawnedEnemies.current, ...spawned]
    setEnemySpawns((current) => [...current, ...spawned])
    spawned.filter((enemy) => enemy.target).forEach((enemy) => {
      setTeammates((current) => current[enemy.target!] === 'ready' ? { ...current, [enemy.target!]: 'threatened' } : current)
    })
    const carrier = spawned.find((enemy) => enemy.variant === 'carrier')
    if (carrier) {
      setBossHealth(carrier.health)
      setBossMaxHealth(carrier.health)
      setStatus('HEAVY CARRIER INBOUND · TARGET CORE SYSTEMS')
    }
  }, [])

  const detonateBomb = useCallback(() => {
    const cleared = spawnedEnemies.current.filter((enemy) => enemy.variant !== 'carrier' && enemy.z + (world.current.distance - enemy.bornAt) < 5)
    spawnedEnemies.current = spawnedEnemies.current.filter((enemy) => enemy.variant === 'carrier' || enemy.z + (world.current.distance - enemy.bornAt) > 5)
    setEnemySpawns((current) => current.filter((enemy) => enemy.variant === 'carrier' || enemy.z + (world.current.distance - enemy.bornAt) > 5))
    cleared.forEach((enemy) => removeEnemy(enemy))
    setScore((current) => current + cleared.length * 8)
    setStatus('PULSE BOMB · AIRSPACE CLEARED')
  }, [removeEnemy])

  const hitEnemy = useCallback((enemyId: string) => {
    const handle = enemies.current.get(enemyId)
    if (!handle?.alive) return
    const enemy = spawnedEnemies.current.find((candidate) => candidate.id === enemyId)
    if (!enemy) return
    handle.alive = false
    const nextHealth = Math.max(0, enemy.health - 1)
    setEnemySpawns((current) => current.map((candidate) => candidate.id === enemyId ? { ...candidate, health: nextHealth } : candidate))
    spawnedEnemies.current = spawnedEnemies.current.map((candidate) => candidate.id === enemyId ? { ...candidate, health: nextHealth } : candidate)
    if (enemy.variant === 'carrier') setBossHealth(nextHealth)
    setScore((current) => current + (enemy.variant === 'carrier' ? 25 : enemy.variant === 'heavy' ? 20 : enemy.variant === 'turret' ? 15 : 10))
    if (nextHealth <= 0) {
      removeEnemy(enemy)
      if (enemy.variant === 'carrier') {
        setStatus('CARRIER CORE DESTROYED · SKYLINE SECURED')
        setStageState('won')
        setRunning(false)
      }
    } else {
      handle.alive = true
      setStatus(`${enemy.variant.toUpperCase()} HIT · ${nextHealth} ARMOR REMAINS`)
    }
  }, [removeEnemy])

  const reset = () => {
    input.current.keys.clear()
    input.current.justPressed.clear()
    lastTap.current = Number.NEGATIVE_INFINITY
    const nextWorld = initialWorld()
    Object.assign(world.current, nextWorld)
    const nextPlayer = initialPlayer()
    player.current.position.copy(nextPlayer.position)
    player.current.target.copy(nextPlayer.target)
    player.current.velocity.copy(nextPlayer.velocity)
    player.current.invincibleUntil = nextPlayer.invincibleUntil
    player.current.barrel = nextPlayer.barrel
    lasers.current.clear()
    enemies.current.clear()
    encounterCursor.current = 0
    spawnedEnemies.current = []
    gameOver.current = false
    setEnemySpawns([])
    setLaserSpecs([])
    setScore(0)
    setShield(100)
    setBombs(3)
    setBossHealth(0)
    setBossMaxHealth(0)
    setDistance(0)
    setTeammates({ lyra: 'ready', rook: 'ready', pip: 'ready' })
    setStatus('ESCORT THE CONVOY · CLEAR THE SKYLINE')
    setStageState('live')
    setRunning(true)
    setRunId((current) => current + 1)
  }

  return (
    <div className="game-shell" role="application" tabIndex={0} aria-label="Skyline Ace rail shooter" aria-describedby="keyboard-controls">
      <Canvas
        key={runId}
        className="game-canvas"
        frameloop={running ? 'always' : 'demand'}
        aria-hidden="true"
        camera={{ position: [0, 1.1, 10], fov: 58, near: 0.1, far: 260 }}
        dpr={[1, 1.75]}
        gl={{ antialias: true, powerPreference: 'high-performance' }}
      >
        <color attach="background" args={['#061326']} />
        <fog attach="fog" args={['#061326', 36, 190]} />
        <ambientLight color="#7ebed0" intensity={0.5} />
        <directionalLight color="#b7e5ff" intensity={2.1} position={[-12, 18, 20]} />
        <directionalLight color="#4d79c4" intensity={1.4} position={[14, 4, -50]} />
        <GameScene
          flight={flight}
          running={running}
          lasers={lasers.current}
          enemies={enemies.current}
          gameOver={gameOver}
          enemySpawns={enemySpawns}
          laserSpecs={laserSpecs}
          onEnemyExpired={expireEnemy}
          onEnemyFire={(origin, direction, speed) => spawnLaser('enemy', origin, direction, speed)}
          onLaserExpired={expireLaser}
          registerEnemy={registerEnemy}
          unregisterEnemy={unregisterEnemy}
          registerLaser={registerLaser}
          unregisterLaser={unregisterLaser}
          bombs={bombs}
          onBomb={() => { setBombs((current) => current - 1); detonateBomb() }}
          onPlayerFire={(origin) => spawnLaser('player', origin)}
          onEncounter={spawnEncounter}
          onHitEnemy={hitEnemy}
          onDamagePlayer={damagePlayer}
          onBarrel={triggerBarrel}
          onStatus={setStatus}
          onScore={(amount) => setScore((current) => current + amount)}
          onDistance={setDistance}
        />
      </Canvas>

      <div className="hud" aria-label="Mission telemetry">
        <div className="hud__top">
          <div className="hud__cluster">
            <div><div className="hud__label">score</div><div className="hud__value hud__value--score">{score.toString().padStart(5, '0')}</div></div>
            <div><div className="hud__label">shield</div><div className="shield" role="progressbar" aria-label="Shield strength" aria-valuemin={0} aria-valuemax={100} aria-valuenow={shield}><div className="shield__fill" aria-hidden="true" style={{ width: `${shield}%` }} /></div></div>
          </div>
          <div><div className="hud__label">bombs</div><div className="hud__value">{bombs}</div></div>
        </div>
        <div className="hud__mission"><strong>SECTOR 01 · SKYLINE COAST</strong><span>R3F rail-shooter vertical slice · {Math.floor(distance)}m</span><span>THREAT {Math.round(normalizedLevelProgress(distance) * 100)}% · AIM {Math.round(getDifficulty(normalizedLevelProgress(distance)).accuracy * 100)}% · WAVE ×{getDifficulty(normalizedLevelProgress(distance)).waveDensity.toFixed(1)}</span></div>
        {bossHealth > 0 && bossMaxHealth > 0 && <div className="boss-hud" role="status" aria-label={`Carrier threat: ${bossHealth} of ${bossMaxHealth} armor remaining`}><div className="hud__label">carrier threat · {bossHealth}/{bossMaxHealth} armor</div><div className="boss-hud__bar" role="progressbar" aria-label="Carrier armor" aria-valuemin={0} aria-valuemax={bossMaxHealth} aria-valuenow={bossHealth}><div className="boss-hud__fill" style={{ width: `${Math.round((bossHealth / bossMaxHealth) * 100)}%` }} /></div></div>}
        <div className={`status${shield < 35 ? ' status--danger' : ''}`} role="status" aria-live="polite" aria-atomic="true">{status}</div>
        <div className="team">
          {TEAM.map((member) => (
            <div key={member.id} className={`team__member team__member--${teammates[member.id]}`}>
              <span>{member.name}</span><span className="team__role">{teammates[member.id] === 'ready' ? member.role : teammates[member.id]}</span>
            </div>
          ))}
        </div>
        <div className="controls" id="keyboard-controls" role="note"><kbd>WASD</kbd> / <kbd>ARROWS</kbd> flight · <kbd>SPACE</kbd> fire · <kbd>SHIFT</kbd> boost<br /><kbd>E</kbd> roll · double-tap <kbd>A/D</kbd> · <kbd>Q</kbd> bomb</div>
      </div>

      <TouchControls input={input} bombs={bombs} onBarrel={triggerBarrel} onBomb={() => { if (bombs > 0) { setBombs((current) => current - 1); detonateBomb() } }} />

      {stageState !== 'live' && (
        <div className="overlay">
          <div className="overlay__card">
            <div className="overlay__eyebrow">MISSION {stageState === 'won' ? 'COMPLETE' : 'FAILED'}</div>
            <h1>{stageState === 'won' ? 'SKYLINE SECURED' : 'SIGNAL LOST'}</h1>
            <p>{stageState === 'won' ? `Carrier core neutralized. Final score ${score.toString().padStart(5, '0')}.` : 'The escort corridor is compromised. Recalibrate and fly again.'}</p>
            <button type="button" onClick={reset}>REDEPLOY</button>
          </div>
        </div>
      )}
    </div>
  )
}

interface TouchControlsProps {
  input: MutableRefObject<InputState>
  bombs: number
  onBarrel: (direction: number) => void
  onBomb: () => void
}

function TouchControls({ input, bombs, onBarrel, onBomb }: TouchControlsProps) {
  const hold = (code: string) => input.current.keys.add(code)
  const release = (code: string) => input.current.keys.delete(code)
  const onPointerDown = (code: string) => (event: ReactPointerEvent<HTMLButtonElement>) => {
    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    hold(code)
  }
  const onPointerUp = (code: string) => (event: ReactPointerEvent<HTMLButtonElement>) => {
    event.preventDefault()
    release(code)
  }
  const tap = (code: string) => {
    hold(code)
    window.setTimeout(() => release(code), 120)
  }

  return (
    <div className="touch-controls" aria-label="Touch flight controls">
      <div className="touch-controls__dpad" aria-label="Flight direction">
        <button type="button" aria-label="Move up" onPointerDown={onPointerDown('ArrowUp')} onPointerUp={onPointerUp('ArrowUp')} onPointerCancel={onPointerUp('ArrowUp')} onClick={() => tap('ArrowUp')}>▲</button>
        <button type="button" aria-label="Move left" onPointerDown={onPointerDown('ArrowLeft')} onPointerUp={onPointerUp('ArrowLeft')} onPointerCancel={onPointerUp('ArrowLeft')} onClick={() => tap('ArrowLeft')}>◀</button>
        <button type="button" aria-label="Move down" onPointerDown={onPointerDown('ArrowDown')} onPointerUp={onPointerUp('ArrowDown')} onPointerCancel={onPointerUp('ArrowDown')} onClick={() => tap('ArrowDown')}>▼</button>
        <button type="button" aria-label="Move right" onPointerDown={onPointerDown('ArrowRight')} onPointerUp={onPointerUp('ArrowRight')} onPointerCancel={onPointerUp('ArrowRight')} onClick={() => tap('ArrowRight')}>▶</button>
      </div>
      <div className="touch-controls__actions">
        <button type="button" aria-label="Fire" onPointerDown={onPointerDown('Space')} onPointerUp={onPointerUp('Space')} onPointerCancel={onPointerUp('Space')} onClick={() => tap('Space')}>FIRE</button>
        <button type="button" aria-label="Boost" onPointerDown={onPointerDown('ShiftLeft')} onPointerUp={onPointerUp('ShiftLeft')} onPointerCancel={onPointerUp('ShiftLeft')} onClick={() => tap('ShiftLeft')}>BOOST</button>
        <button type="button" aria-label="Barrel roll" onClick={() => onBarrel(1)}>ROLL</button>
        <button type="button" aria-label={`Pulse bomb, ${bombs} remaining`} disabled={bombs === 0} onClick={onBomb}>BOMB</button>
      </div>
    </div>
  )
}

interface GameSceneProps {
  flight: FlightRuntime
  running: boolean
  lasers: Map<string, LaserHandle>
  enemies: Map<string, EnemyHandle>
  gameOver: MutableRefObject<boolean>
  enemySpawns: EnemySpawn[]
  laserSpecs: LaserSpec[]
  onEnemyExpired: (spawn: EnemySpawn) => void
  onEnemyFire: (origin: THREE.Vector3, direction: THREE.Vector3, speed: number) => void
  onLaserExpired: (id: string) => void
  registerEnemy: (handle: EnemyHandle) => void
  unregisterEnemy: (id: string) => void
  registerLaser: (handle: LaserHandle) => void
  unregisterLaser: (id: string) => void
  bombs: number
  onBomb: () => void
  onPlayerFire: (origin: THREE.Vector3) => void
  onEncounter: (encounter: Encounter, index: number) => void
  onHitEnemy: (enemyId: string) => void
  onDamagePlayer: (amount: number) => void
  onBarrel: (direction: number) => void
  onStatus: (status: string) => void
  onScore: (amount: number) => void
  onDistance: (distance: number) => void
}

interface SimulationProps {
  flight: FlightRuntime
  running: boolean
  bombs: number
  lasers: Map<string, LaserHandle>
  enemies: Map<string, EnemyHandle>
  gameOver: MutableRefObject<boolean>
  onBomb: () => void
  onPlayerFire: (origin: THREE.Vector3) => void
  onEncounter: (encounter: Encounter, index: number) => void
  onHitEnemy: (enemyId: string) => void
  onDamagePlayer: (amount: number) => void
  onBarrel: (direction: number) => void
  onStatus: (status: string) => void
  onScore: (amount: number) => void
  onDistance: (distance: number) => void
}

function Simulation({ flight, running, bombs, lasers, enemies, gameOver, onBomb, onPlayerFire, onEncounter, onHitEnemy, onDamagePlayer, onBarrel, onStatus, onScore, onDistance }: SimulationProps) {
  const encounterCursor = useRef(0)
  const lastShot = useRef(0)
  const lastHudUpdate = useRef(0)

  useFrame((_, delta) => {
    if (!running || gameOver.current) return
    const { world, player, input } = flight
    world.time += delta
    const now = world.time
    world.boost = input.keys.has('ShiftLeft') || input.keys.has('ShiftRight')
    world.distance += delta * world.speed * (world.boost ? 1.75 : 1)

    while (encounterCursor.current < ENCOUNTERS.length && world.distance >= ENCOUNTERS[encounterCursor.current].at) {
      const index = encounterCursor.current
      onEncounter(ENCOUNTERS[index], index)
      encounterCursor.current += 1
    }

    if (input.justPressed.has('KeyE')) onBarrel(1)
    if (input.justPressed.has('KeyQ') && bombs > 0) onBomb()
    if (input.keys.has('Space') && now - lastShot.current > 0.16) {
      lastShot.current = now
      const origin = player.position.clone()
      origin.z -= 1.2
      onPlayerFire(origin)
    }

    for (const laser of lasers.values()) {
      if (!laser.alive) continue
      if (laser.owner === 'player') {
        for (const enemy of enemies.values()) {
          if (!enemy.alive) continue
          const dx = laser.position.x - enemy.position.x
          const dy = laser.position.y - enemy.position.y
          const dz = Math.abs(laser.position.z - enemy.position.z)
          if (Math.hypot(dx, dy) < enemy.radius && dz < 1.9) {
            laser.alive = false
            onHitEnemy(enemy.id)
            break
          }
        }
      } else {
        const dx = laser.position.x - player.position.x
        const dy = laser.position.y - player.position.y
        const dz = Math.abs(laser.position.z - player.position.z)
        if (Math.hypot(dx, dy) < 0.9 && dz < 1.8) {
          laser.alive = false
          if (now < player.invincibleUntil) {
            onScore(5)
            onStatus('DEFLECTED')
          } else {
            onDamagePlayer(9)
            onStatus('HULL STRIKE · EVADE INCOMING FIRE')
          }
        }
      }
    }

    if (now - lastHudUpdate.current > 0.1) {
      lastHudUpdate.current = now
      onDistance(world.distance)
    }
    input.justPressed.clear()
  })
  return null
}

function GameScene({ flight, running, lasers, enemies, gameOver, enemySpawns, laserSpecs, onEnemyExpired, onEnemyFire, onLaserExpired, registerEnemy, unregisterEnemy, registerLaser, unregisterLaser, bombs, onBomb, onPlayerFire, onEncounter, onHitEnemy, onDamagePlayer, onBarrel, onStatus, onScore, onDistance }: GameSceneProps) {
  return (
    <>
      <Simulation
        flight={flight}
        running={running}
        bombs={bombs}
        onBomb={onBomb}
        onPlayerFire={onPlayerFire}
        onEncounter={onEncounter}
        onHitEnemy={onHitEnemy}
        onDamagePlayer={onDamagePlayer}
        onBarrel={onBarrel}
        lasers={lasers}
        enemies={enemies}
        gameOver={gameOver}
        onStatus={onStatus}
        onScore={onScore}
        onDistance={onDistance}
      />
      <CameraRig flight={flight} />
      <Terrain world={flight.world} />
      <Arwing flight={flight} />
      <Reticle flight={flight} />
      {enemySpawns.map((spawn) => (
        <Enemy key={spawn.id} spawn={spawn} world={flight.world} player={flight.player} onExpired={onEnemyExpired} onFire={onEnemyFire} register={registerEnemy} unregister={unregisterEnemy} />
      ))}
      {laserSpecs.map((laser) => (
        <Laser key={laser.id} {...laser} onExpired={onLaserExpired} register={registerLaser} unregister={unregisterLaser} />
      ))}
      <SceneEffects />
    </>
  )
}

