/** Small deterministic hash with every character of an ID and the shot index. */
export function deterministicAimSeed(id: string, shotIndex: number) {
  let hash = 2166136261 >>> 0
  for (let index = 0; index < id.length; index += 1) {
    hash ^= id.charCodeAt(index)
    hash = Math.imul(hash, 16777619) >>> 0
  }
  hash ^= shotIndex >>> 0
  hash = Math.imul(hash, 16777619) >>> 0
  return ((hash / 0xffffffff) * 2) - 1
}

/** Solve a quadratic intercept and cap it so shots never predict an old position. */
export function boundedInterceptTime(
  player: AimPoint,
  velocity: { x: number; y: number },
  origin: AimPoint,
  projectileSpeed: number,
  maxTime = 1.4,
) {
  const rx = player.x - origin.x
  const ry = player.y - origin.y
  const rz = player.z - origin.z
  const vx = velocity.x
  const vy = velocity.y
  const a = vx * vx + vy * vy - projectileSpeed * projectileSpeed
  const b = 2 * (rx * vx + ry * vy)
  const c = rx * rx + ry * ry + rz * rz
  let time = c > 0 ? Math.sqrt(c) / projectileSpeed : 0.15
  if (Math.abs(a) > 0.001) {
    const discriminant = b * b - 4 * a * c
    if (discriminant >= 0) {
      const root = Math.sqrt(discriminant)
      const first = (-b - root) / (2 * a)
      const second = (-b + root) / (2 * a)
      const candidates = [first, second].filter((candidate) => candidate > 0)
      if (candidates.length > 0) time = Math.min(...candidates)
    }
  }
  return Math.min(maxTime, Math.max(0.15, time))
}

