edits.newText:
function TouchControls({ input, bombs, onBarrel, onBomb }: TouchControlsProps) {
  const releaseTimers = useRef(new Map<string, number>())
  useEffect(() => () => {
    releaseTimers.current.forEach((timer) => window.clearTimeout(timer))
    releaseTimers.current.clear()
  }, [])
  const hold = (code: string) => input.current.keys.add(code)
  const release = (code: string) => {
    input.current.keys.delete(code)
    const timer = releaseTimers.current.get(code)
    if (timer !== undefined) {
      window.clearTimeout(timer)
      releaseTimers.current.delete(code)
    }
  }

